export const douyinArtifactVersions = [{"id":"dy-av-00-script","artifactId":"dy-art-00-script","versionNumber":1,"contentText":"为什么你的AI装上了，但是产出任务的一个效果却不尽人意？我昨天和两位朋友大概聊了有三个小时，一个是做助贷的一个自媒体的同学，另外一个是做电商的一个同学。我发现他们卡在的其实是同一件事情。并不是工具不行，是没有拆解工作流的思维。我们就来详细讲一讲输入、输出以及处理端这个链路。以输入端为例，我们在没有原创能力的时候，可以去借鉴其他博主的爆款，不管是改写还是什么都可以。还有一个点就是助贷行业，它这个行业对于数据源的要求是比较高的，我们尽量去订阅一手的数据源，保证我们内容是真实可信的，以及我们产量有保证的。","contentData":{"hook":"为什么你的 AI 装上了，但产出任务的一个效果却不尽人意？","cta":"评论区说说你的工作流卡在哪一步，下条我挑 1 个真实场景拆给你看","coreQuotes":["AI 产出差不是工具的锅，是工作流没拆解。","我们绝大多数的日常需求，现在的所有模型其实都能解决——我们真正缺的，是没有拆解工作流的思维。","拿到一个需求，最简单的拆解方式：输入 / 处理 / 输出 + 端到端可视化。","1V1 不是单方面教对方，是互相学习、互惠互赢的过程。"]},"changeSummary":"从知识库口播稿初始化","createdByType":"user","aiTaskId":null,"createdAt":"2026-06-17T17:10:30.000Z"},{"id":"dy-av-01-script","artifactId":"dy-art-01-script","versionNumber":1,"contentText":"上周一个销售朋友粉丝找我装我开源的知识库。他自己其实装了好几个 Agent，Claude、Codex。但是也不知道在他实际工作中，怎么用上了这个 AI。在两个小时的远程会议中，我给他打通了知识库的入库、飞书机器人的接入、Hermes 的接入，以及 Codex 的接入，并按照现有的规范体系安装他的知识库。但是我没想到的是这件事给我目前在做的产品也带来了新的想法。在做这件事情的时候，第一步我们先进行了一个调研。我们在 IM 上聊了三天，他平常的使用场景是什么？想用 AI 做什么？然后给他发了一个问卷，一共是 8 道题，搞清楚他真正想要的结果。","contentData":{"hook":"你 AI 工具装了一堆，是不是还是不知道用在哪？","cta":"评论区写下你最想让 AI 跑通的那个具体任务，下条我挑 1 个拆给你看","coreQuotes":["AI 赋能不是再装一个工具，而是跑通一条你能自己重复执行的工作流。","工具本身不是重点。工具在这条工作流里各自只负责一件事，前后接得起来——这才是重点。","真正决定工作流能不能长期用的，不是第一次有没有跑通，而是下次出错时你能不能自己救回来。","好的 1v1 不是我单方面讲一套软件——是业务的人走近 AI，做技术的人走近业务。"]},"changeSummary":"从知识库口播稿初始化","createdByType":"user","aiTaskId":null,"createdAt":"2026-06-07T12:02:41.000Z"},{"id":"dy-av-03-script","artifactId":"dy-art-03-script","versionNumber":1,"contentText":"你现在看到的不是一个笔记列表。这是我的知识库控制台。左上角这条贪吃蛇动画是一整年的活动热力图——不是静态色块，算法会沿着最长活跃路径画出一条蛇。下面八个工作区：系统、收件箱、日记、知识、项目、资源、输出、归档，每个都有独立职责。右侧是今天的待办和快捷操作。整个东西是一个黑曜石插件，代码全部公开。但这个控制台不是重点。重点是：它背后连着一套可以直接复制的知识库模板。你把模板仓库拉到本地，然后在这个目录里打开任何一个能读规则文件的智能体，说一句：帮我初始化这个知识库。","contentData":{"hook":"你现在看到的不是一个笔记列表。这是我的知识库控制台。","cta":"去 GitHub clone thirdspace-vault-template，再安装/启用 thirdspace-dashboard。","coreQuotes":["以前知识库是文件夹，现在它可以是一个由 Agent 驱动的操作系统。","我真正开源的不是目录结构，而是一套让 Agent 能读懂、能路由、能执行的协议。","人负责表达意图，系统负责把意图落到正确的位置。"]},"changeSummary":"从知识库口播稿初始化","createdByType":"user","aiTaskId":null,"createdAt":"2026-05-28T15:10:18.000Z"},{"id":"dy-av-06-script","artifactId":"dy-art-06-script","versionNumber":1,"contentText":"Claude Code 工程师 Thariq 发了一篇长文。1200万阅读，2.3万次转发，评论区几乎没有人质疑。帖子的大意是：AI 时代，HTML 完胜 Markdown。他给了四个「铁证」：AI生成效果、视觉体验、分享成本、交互能力。听起来无懈可击，对吧？但这篇帖子犯了一个根本性的错误——它在用「传播层」的标准，来评判「存储层」的工具。这里有两种完全不同的消费者：机器 vs 人。AI读取效率、版本控制、RAG检索、知识关联，这不是同一场比赛。知识有它的生命周期：创作、整理、传播、归档，每个阶段需要不同的工具。","contentData":{"hook":"Claude Code 工程师 Thariq 发了一篇长文，1200万阅读、2.3万次转发，说AI时代HTML完胜Markdown。","cta":"下次有人告诉你「Markdown已死」，问他：你的知识从哪里来？如果答案是「从人类的思考中来」，Markdown永远有它的位置。","coreQuotes":["「它在用传播层的标准，来评判存储层的工具。」","「这不是同一场比赛。」","「Markdown 文件本身就是一种 API。」","「格式不是目的，知识的存储、传递、传承才是目的。」"]},"changeSummary":"从知识库口播稿初始化","createdByType":"user","aiTaskId":null,"createdAt":"2026-05-22T16:32:40.000Z"},{"id":"dy-av-07-script","artifactId":"dy-art-07-script","versionNumber":1,"contentText":"你有没有这种感觉——AI很聪明，但每次聊到你的事情，它总是一脸茫然。你上个月做了什么项目？AI不知道。你和谁有过重要对话？AI不知道。你最近学到了什么？AI还是不知道。因为它没有你的上下文。而这个上下文，就是未来你和别人AI差距的核心。你跟AI聊了两天，第三天它不认识你了。你跟它说「我们上次讨论的那个」，它说「抱歉，我不太清楚」。——不是你的表达有问题，是AI根本没有「记住你」这个功能。这个问题有个名字，叫「Lost in the Middle」，论文专门给它起的。IBM把上下文窗口叫做AI的「工作记忆」。","contentData":{"hook":"你有没有这种感觉——AI很聪明，但每次聊到你的事情，它总是一脸茫然。","cta":"今天建好第一个文件夹（命名「AI时代知识库」），选一件每天都在做的事，想想哪件最值得静默积累。","coreQuotes":["「AI很聪明，但AI不了解你。而这个上下文，就是未来你和别人AI差距的核心。」","「知识不是被灌输的，而是从内部唤醒的。」","「你正常工作，日志自己长出来。」"]},"changeSummary":"从知识库口播稿初始化","createdByType":"user","aiTaskId":null,"createdAt":"2026-05-20T23:55:00.000Z"}] as const;
